#!/usr/bin/env python3
"""Compute ground truth for CSX-159_Q2."""

from __future__ import annotations

import html
import json
import re
from pathlib import Path


TASK_ID = "CSX-159_Q2"
EVENT_ID = "CSX-159"
TARGET_FAMILY = "numeric_diagnosis"

NOAA_REPORT = "data/event_reports/event_reports_001_Locked_anchor_report_NOAA_Climate.gov.html"
WHO_REPORT = "data/other/other_001_WHO_Western_Pacific_El_Nino_and_health_in_the_Pacific.html"
ANCHOR_JSON = (
    "data/event_reports/"
    "event_reports_003_Locked_event_anchor_2015-2016_El_Nino_drought_in_western_Pacific_island_capitals.json"
)


def repo_root() -> Path:
    return Path(__file__).resolve().parents[3]


def package_root() -> Path:
    return repo_root() / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID


def output_path() -> Path:
    return Path(__file__).resolve().with_name("computed_gt.json")


def read_json(rel_path: str) -> dict:
    with (package_root() / rel_path).open("r", encoding="utf-8-sig") as f:
        return json.load(f)


def read_text(rel_path: str) -> str:
    return (package_root() / rel_path).read_text(encoding="utf-8-sig", errors="replace")


def html_to_text(rel_path: str) -> str:
    raw = read_text(rel_path)
    text = re.sub(r"<script\b.*?</script>", " ", raw, flags=re.IGNORECASE | re.DOTALL)
    text = re.sub(r"<style\b.*?</style>", " ", text, flags=re.IGNORECASE | re.DOTALL)
    text = re.sub(r"<[^>]+>", " ", text)
    text = html.unescape(text)
    text = text.replace("\u201c", '"').replace("\u201d", '"').replace("\u2019", "'")
    return re.sub(r"\s+", " ", text).strip()


def require_float(pattern: str, text: str, label: str) -> float:
    match = re.search(pattern, text, flags=re.IGNORECASE)
    if not match:
        raise ValueError(f"Could not extract {label}")
    return float(match.group(1))


def contains(text: str, phrase: str) -> bool:
    return phrase.lower() in text.lower()


def main() -> None:
    anchor = read_json(ANCHOR_JSON)
    noaa_text = html_to_text(NOAA_REPORT)
    who_text = html_to_text(WHO_REPORT)

    observed_inches = require_float(r"only about ([0-9]+(?:\.[0-9]+)?) inches of rain", noaa_text, "observed rainfall")
    below_average_inches = require_float(r"nearly ([0-9]+(?:\.[0-9]+)?) inches below average", noaa_text, "rainfall deficit")
    if re.search(r"Koror, the capital of Palau, has seen a third of its normal rainfall", noaa_text, re.IGNORECASE):
        stated_fraction_of_normal = 1 / 3
    else:
        stated_fraction_of_normal = require_float(
            r"Koror, the capital of Palau, has seen ([0-9]+(?:\.[0-9]+)?) of its normal rainfall",
            noaa_text,
            "fraction of normal",
        )

    triggers = {
        "dam_dried_up": bool(
            re.search(r"Ngerimel Dam, which supplies water to Koror, has dried up", noaa_text, flags=re.IGNORECASE)
        ),
        "river_very_low": bool(
            re.search(
                r"only other source of drinking water, the Ngerikiil River, are very low",
                noaa_text,
                flags=re.IGNORECASE,
            )
        ),
        "rationing_begun": contains(noaa_text, "water rationing has begun"),
    }
    trigger_count = sum(1 for value in triggers.values() if value)

    implied_normal_inches = observed_inches + below_average_inches
    deficit_share = below_average_inches / implied_normal_inches
    uncapped_wspi = deficit_share + 0.10 * trigger_count
    wspi = min(1.0, uncapped_wspi)
    threshold_state = "capped_maximum" if uncapped_wspi >= 1.0 and round(wspi, 3) == 1.0 else "below_cap"
    final_label = (
        "acute_freshwater_drought_health_stress"
        if threshold_state == "capped_maximum" and trigger_count == 3
        else "not_maximum_stress"
    )

    mechanism_flags = {
        "el_nino_shifted_walker_circulation": contains(noaa_text, "shifted Walker Circulation"),
        "rainfall_shifted_east": contains(noaa_text, "rainfall to fall much farther east than normal"),
        "western_pacific_left_drier": contains(noaa_text, "western Pacific, much drier than normal"),
    }
    impact_flags = {
        "food_security_public_health_economy": contains(
            noaa_text, "negatively impact food security, public health, and the economy"
        ),
        "reduced_water_supplies": contains(noaa_text, "Greatly reduced water supplies"),
    }
    who_flags = {
        "potable_water_scarcity_health": contains(who_text, "scarcity of potable water"),
        "drinking_water_quantity_quality": contains(who_text, "Quantity and quality of drinking water supply should be ensured"),
        "emergency_water_conservation": contains(who_text, "Emergency water conservation and catering systems should also be considered"),
        "hospitals_safe_drinking_water": contains(who_text, "Safe drinking water and improved sanitation"),
    }

    answer = {
        "target_family": TARGET_FAMILY,
        "rainfall": {
            "observed_in": round(observed_inches, 3),
            "below_average_in": round(below_average_inches, 3),
            "implied_normal_in": round(implied_normal_inches, 3),
            "deficit_share": round(deficit_share, 3),
        },
        "triggers": {
            "dam_dried_up": triggers["dam_dried_up"],
            "river_very_low": triggers["river_very_low"],
            "rationing_begun": triggers["rationing_begun"],
            "count": trigger_count,
        },
        "wspi": {
            "uncapped": round(uncapped_wspi, 3),
            "capped": round(wspi, 3),
        },
        "threshold_state": threshold_state,
        "final_label": final_label,
    }

    rubric = {
        "total_points": 20,
        "criteria": [
            {
                "name": "Required JSON answer and final diagnosis",
                "points": 3,
                "description": "Returns the six requested top-level fields with threshold_state = capped_maximum and final_label = acute_freshwater_drought_health_stress.",
                "partial_credit": "Award 1-2 points for the right label with missing, extra, or poorly named fields.",
            },
            {
                "name": "Rainfall deficit ledger",
                "points": 4,
                "description": "Uses 8.0 inches observed rainfall, 22.0 inches below average, 30.0 inches implied normal rainfall, and computes deficit_share = 22/30 = 0.733.",
                "partial_credit": "Award 2-3 points for the correct formula with one missing or slightly misrounded intermediate value; award 1 point for recognizing a major rainfall deficit without a valid calculation.",
            },
            {
                "name": "Acute trigger ledger",
                "points": 4,
                "description": "Marks the dam dried up, river very low, and rationing begun as true and counts three acute water-supply triggers.",
                "partial_credit": "Award 1 point for one correct trigger, 2 points for two correct triggers, or 3 points for a correct count without naming the supported conditions.",
            },
            {
                "name": "WSPI formula and cap",
                "points": 4,
                "description": "Computes uncapped_WSPI = 0.733 + 0.10 * 3 = 1.033, applies min(1.0, uncapped_WSPI), and reports capped WSPI = 1.000.",
                "partial_credit": "Award 2-3 points for the correct uncapped value without the cap or for a correct cap with a minor arithmetic error.",
            },
            {
                "name": "Threshold proof",
                "points": 3,
                "description": "Compares the uncapped value with the 1.0 cap, reports threshold_state = capped_maximum, and ties all three true triggers to the final label.",
                "partial_credit": "Award 1-2 points for stating maximum stress without showing both the cap test and the trigger test.",
            },
            {
                "name": "Concision and overclaim control",
                "points": 2,
                "description": "Keeps the answer compact and avoids claims that WSPI is official, exact population affected is known, or anthropogenic climate change is proven as the direct cause of this specific drought.",
                "partial_credit": "Award 1 point for a mostly correct answer with one minor overstatement.",
            },
        ],
    }

    gt = {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "target_family": TARGET_FAMILY,
        "task_type": "numeric",
        "evaluation_mode": "hybrid",
        "difficulty_level": "L2",
        "primary_gt": answer,
        "key_values": {
            "event_window": anchor["temporal_window"],
            "location_text": anchor["spatial_window"]["location_text"],
            "observed_rainfall_inches": observed_inches,
            "rainfall_below_average_inches": below_average_inches,
            "implied_normal_rainfall_inches": implied_normal_inches,
            "deficit_share_exact": deficit_share,
            "stated_fraction_of_normal_since_march_1": stated_fraction_of_normal,
            "acute_water_supply_triggers": triggers,
            "acute_water_supply_trigger_count": trigger_count,
            "uncapped_wspi": uncapped_wspi,
            "water_stress_priority_index": wspi,
            "threshold_state": threshold_state,
            "final_label": final_label,
            "tolerances": {"rainfall_in": 0.1, "deficit_share": 0.001, "wspi": 0.001},
            "formula": "WSPI = min(1.0, deficit_share + 0.10 * trigger_count)",
            "threshold_state_rule": "capped_maximum iff uncapped_WSPI >= 1.0 and capped WSPI rounds to 1.000",
            "final_label_rule": "acute_freshwater_drought_health_stress iff threshold_state is capped_maximum and all three acute water-supply triggers are true",
            "mechanism_flags": mechanism_flags,
            "impact_flags": impact_flags,
            "who_guidance_flags": who_flags,
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": [
                NOAA_REPORT,
                WHO_REPORT,
                ANCHOR_JSON,
            ],
            "notes": "Deterministically extracts rainfall and water-supply triggers for a hybrid numeric threshold-ledger task.",
        },
        "rubric": rubric,
    }

    output_path().write_text(json.dumps(gt, indent=2, sort_keys=False) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
